<?php
namespace App\Services;use App\Models\VideoClip;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use RuntimeException;use Symfony\Component\Process\ExecutableFinder;use Symfony\Component\Process\Process;
class VideoClipRenderer{
 public function dimensions(string $ratio):array{return match($ratio){'1:1'=>[1080,1080],'16:9'=>[1920,1080],default=>[1080,1920]};}
 public function render(VideoClip $clip):void{$video=$clip->video;if($video->provider!=='file'||str_starts_with($video->video_path,'http'))throw new RuntimeException('Somente vídeos locais podem ser recortados.');$binary=(string)config('media.ffmpeg_binary','ffmpeg');$resolved=(new ExecutableFinder)->find($binary);if(!$resolved&&is_file($binary))$resolved=$binary;if(!$resolved)throw new RuntimeException('FFmpeg não encontrado. Configure FFMPEG_BINARY.');
  $input=Storage::disk('public')->path($video->video_path);if(!is_file($input))throw new RuntimeException('Arquivo de vídeo original não encontrado.');[$w,$h]=$this->dimensions($clip->aspect_ratio);$output='shorts/'.Str::uuid().'.mp4';$absolute=Storage::disk('public')->path($output);if(!is_dir(dirname($absolute)))mkdir(dirname($absolute),0775,true);$start=$clip->starts_at_ms/1000;$duration=($clip->ends_at_ms-$clip->starts_at_ms)/1000;$filter="scale={$w}:{$h}:force_original_aspect_ratio=increase,crop={$w}:{$h}";
  $process=new Process([$resolved,'-y','-ss',(string)$start,'-i',$input,'-t',(string)$duration,'-vf',$filter,'-c:v','libx264','-preset','medium','-c:a','aac','-movflags','+faststart',$absolute]);$process->setTimeout(600);$process->run();if(!$process->isSuccessful())throw new RuntimeException(Str::limit($process->getErrorOutput(),2000,''));$clip->update(['status'=>'pending_review','output_path'=>$output,'rendered_at'=>now(),'error_message'=>null]);}
}
